#!/usr/bin/env node
/**
 * Cinejoy webOS - Milestone UI-M3 Empirical Adversarial Challenger Test Suite
 * File: tests/adversarial-ui-m3-challenger1.js
 * 
 * Agent: challenger_ui_m3_1 (critic, specialist)
 * Roles: critic (adversarial stress testing), specialist (webOS 8.5 UI architecture)
 * Target: CineJoy LG webOS 8.5 Media Player HUD Overlay & Scrubber Modernization
 * 
 * Adversarially challenges and verifies:
 * 1. Scrub bar geometry & expansion (8px-to-12px expanding track, cubic-bezier transition, glow)
 * 2. Scrub thumb geometry & boundary math (14px-to-24px halo thumb, 5px halo ring, 0-100% clamping)
 * 3. Timeline typography & countdown remaining (Google Sans tabular numbers, #e8eaed, -HH:MM:SS #bdc1c6)
 * 4. Seeking visual feedback toast (±15s visual indicator, backward compat ±10s, 100-burst hammering)
 * 5. Autonomous 4000ms idle timer (3950ms boundary reset, paused suspension, modal dialog suspension)
 * 6. Zero DOM sinks, XSS injection fuzzing & VDEC blur elimination
 */

'use strict';

const fs = require('fs');
const path = require('path');
const assert = require('assert');

// 1. Resolve JSDOM across known environments
let JSDOM;
try {
  JSDOM = require('jsdom').JSDOM;
} catch (e1) {
  try {
    JSDOM = require('/home/prem/monkeytype/monkeytype/node_modules/.pnpm/jsdom@27.4.0_supports-color@10.2.2/node_modules/jsdom').JSDOM;
  } catch (e2) {
    try {
      JSDOM = require('/home/prem/Documents/movies/netflix/node_modules/jsdom').JSDOM;
    } catch (e3) {
      console.error('FATAL: JSDOM module could not be resolved:', e1.message);
      process.exit(1);
    }
  }
}

// 2. ANSI Terminal Colors
const C = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  cyan: '\x1b[36m',
  yellow: '\x1b[33m',
  magenta: '\x1b[35m',
  gray: '\x1b[90m'
};

let totalChecks = 0;
let passedChecks = 0;
let failedChecks = 0;
const failureList = [];

async function check(suiteId, testId, description, fn) {
  totalChecks++;
  const label = `[${suiteId}.${testId}] ${description}`;
  const start = Date.now();
  try {
    await fn();
    passedChecks++;
    const duration = Date.now() - start;
    console.log(`  ${C.green}✓ PASS${C.reset} ${label} ${C.gray}(${duration}ms)${C.reset}`);
  } catch (err) {
    failedChecks++;
    failureList.push({ label, error: err.message, stack: err.stack });
    console.log(`  ${C.red}✗ FAIL${C.reset} ${label}`);
    console.log(`    ${C.red}Error: ${err.message}${C.reset}`);
  }
}

// 3. Harness Factory with Deterministic Virtual Clock
function createChallengerHarness(options) {
  const opts = options || {};

  const htmlPath = path.resolve(__dirname, '../app/index.html');
  const configPath = path.resolve(__dirname, '../app/js/config.js');
  const navPath = path.resolve(__dirname, '../app/js/navigation.js');
  const tmdbPath = path.resolve(__dirname, '../app/js/tmdb.js');
  const homePath = path.resolve(__dirname, '../app/js/views/home.js');
  const catalogPath = path.resolve(__dirname, '../app/js/views/catalog.js');
  const searchPath = path.resolve(__dirname, '../app/js/views/search.js');
  const detailsPath = path.resolve(__dirname, '../app/js/views/details.js');
  const playerPath = path.resolve(__dirname, '../app/js/player.js');
  const appPath = path.resolve(__dirname, '../app/js/app.js');

  const html = fs.readFileSync(htmlPath, 'utf8');
  const dom = new JSDOM(html, {
    url: 'http://localhost/#home',
    runScripts: 'outside-only'
  });
  const window = dom.window;

  window.__TEST_M5__ = true;

  // Virtualized Clock Engine
  let virtualTime = 0;
  let timerSeq = 1;
  const virtualTimers = new Map();

  const origSetTimeout = window.setTimeout.bind(window);
  const origClearTimeout = window.clearTimeout.bind(window);
  const origSetInterval = window.setInterval.bind(window);
  const origClearInterval = window.clearInterval.bind(window);

  window.advanceClock = function (ms) {
    virtualTime += ms;
    let firedAny = true;
    while (firedAny) {
      firedAny = false;
      const readyTimers = [];
      virtualTimers.forEach((timer, id) => {
        if (timer.fireAt <= virtualTime) {
          readyTimers.push({ id, ...timer });
        }
      });
      readyTimers.sort((a, b) => a.fireAt - b.fireAt);
      for (const t of readyTimers) {
        if (!virtualTimers.has(t.id)) continue;
        firedAny = true;
        if (t.interval) {
          t.fireAt += t.interval;
          virtualTimers.set(t.id, t);
        } else {
          virtualTimers.delete(t.id);
        }
        try {
          t.callback();
        } catch (err) {
          console.error('[VirtualTimer Error]', err);
        }
      }
    }
  };

  window.setTimeout = function (callback, delay) {
    const d = Number(delay) || 0;
    // Intercept timers >= 200ms (idle timer 4000ms, toast 1200ms)
    if (d >= 200) {
      const id = timerSeq++;
      virtualTimers.set(id, { callback, fireAt: virtualTime + d, interval: null });
      return id;
    }
    return origSetTimeout(callback, delay);
  };

  window.clearTimeout = function (id) {
    if (virtualTimers.has(id)) {
      virtualTimers.delete(id);
      return;
    }
    return origClearTimeout(id);
  };

  window.setInterval = function (callback, delay) {
    const d = Number(delay) || 0;
    if (d >= 200) {
      const id = timerSeq++;
      virtualTimers.set(id, { callback, fireAt: virtualTime + d, interval: d });
      return id;
    }
    return origSetInterval(callback, delay);
  };

  window.clearInterval = function (id) {
    if (virtualTimers.has(id)) {
      virtualTimers.delete(id);
      return;
    }
    return origClearInterval(id);
  };

  // Mock layout coordinates
  function makeRect(left, top, width, height) {
    return { left, top, width, height, right: left + width, bottom: top + height, x: left, y: top };
  }

  window.Element.prototype.getBoundingClientRect = function () {
    if (this.style && this.style.display === 'none') return makeRect(0, 0, 0, 0);
    const modalParent = this.closest ? this.closest('.player-modal-backdrop') : null;
    if (modalParent && modalParent.style && modalParent.style.display === 'none') return makeRect(0, 0, 0, 0);

    const id = this.id;
    if (id === 'player-back-btn') return makeRect(96, 54, 54, 54);
    if (id === 'osd-title') return makeRect(174, 54, 800, 40);
    if (id === 'osd-scrubber') return makeRect(240, 920, 1440, 20);
    if (id === 'osd-current-time') return makeRect(96, 914, 120, 32);
    if (id === 'osd-duration-time') return makeRect(1704, 914, 120, 32);
    if (id === 'osd-rewind-btn') return makeRect(815, 960, 54, 54);
    if (id === 'osd-play-btn') return makeRect(893, 953, 68, 68);
    if (id === 'osd-forward-btn') return makeRect(985, 960, 54, 54);
    if (id === 'osd-subtitles-btn') return makeRect(1420, 960, 180, 52);
    if (id === 'osd-server-btn') return makeRect(1616, 960, 180, 52);

    if (id === 'player-subtitles-close-btn') return makeRect(1180, 260, 40, 40);
    if (id === 'player-server-close-btn') return makeRect(1180, 260, 40, 40);

    if (id === 'player-error-retry-btn') return makeRect(740, 580, 180, 52);
    if (id === 'player-error-switch-btn') return makeRect(940, 580, 160, 52);
    if (id === 'player-error-exit-btn') return makeRect(1120, 580, 160, 52);

    if (this.classList && this.classList.contains('modal-list-item')) {
      const idx = this.parentElement ? Array.from(this.parentElement.children).indexOf(this) : 0;
      return makeRect(680, 320 + idx * 60, 560, 52);
    }
    if (id === 'details-play-btn') return makeRect(96, 400, 180, 52);
    return makeRect(96, 100, 100, 40);
  };

  window.Element.prototype.scrollIntoView = function () {};
  window.Element.prototype.scrollTo = function () {};

  // Mock HTMLMediaElement
  const proto = window.HTMLMediaElement.prototype;
  function getState(el) {
    if (!el._mediaState) {
      el._mediaState = {
        currentTime: 0,
        duration: 7200,
        paused: true,
        ended: false,
        seeking: false,
        readyState: 0,
        bufferedRanges: [[0, 0]],
        textTracks: [],
        error: null,
        src: ''
      };
    }
    return el._mediaState;
  }

  Object.defineProperty(proto, 'currentTime', {
    get: function () { return getState(this).currentTime; },
    set: function (val) {
      const s = getState(this);
      s.currentTime = Math.max(0, Math.min(s.duration, Number(val) || 0));
      this.dispatchEvent(new window.Event('timeupdate'));
    },
    configurable: true
  });

  Object.defineProperty(proto, 'duration', {
    get: function () { return getState(this).duration; },
    set: function (val) {
      const s = getState(this);
      s.duration = Number(val) || 0;
      this.dispatchEvent(new window.Event('durationchange'));
    },
    configurable: true
  });

  Object.defineProperty(proto, 'paused', {
    get: function () { return getState(this).paused; },
    set: function (val) { getState(this).paused = !!val; },
    configurable: true
  });

  Object.defineProperty(proto, 'readyState', {
    get: function () { return getState(this).readyState; },
    set: function (val) { getState(this).readyState = Number(val) || 0; },
    configurable: true
  });

  Object.defineProperty(proto, 'buffered', {
    get: function () {
      const ranges = getState(this).bufferedRanges;
      return {
        length: ranges.length,
        start: function (i) { return ranges[i][0]; },
        end: function (i) { return ranges[i][1]; }
      };
    },
    configurable: true
  });

  Object.defineProperty(proto, 'textTracks', {
    get: function () {
      const s = getState(this);
      if (s.textTracks.length === 0) {
        ['English', 'Spanish'].forEach((lang, idx) => {
          s.textTracks.push({
            id: String(idx),
            label: lang,
            language: lang.slice(0, 2).toLowerCase(),
            kind: 'subtitles',
            mode: 'disabled',
            cues: []
          });
        });
      }
      return s.textTracks;
    },
    configurable: true
  });

  proto.play = function () {
    const s = getState(this);
    s.paused = false;
    s.ended = false;
    s.readyState = 4;
    this.dispatchEvent(new window.Event('play'));
    this.dispatchEvent(new window.Event('playing'));
    return Promise.resolve();
  };
  proto.pause = function () {
    const s = getState(this);
    s.paused = true;
    this.dispatchEvent(new window.Event('pause'));
  };
  proto.load = function () {
    const s = getState(this);
    s.currentTime = 0;
    s.ended = false;
    this.dispatchEvent(new window.Event('loadstart'));
  };
  proto.canPlayType = function () { return 'probably'; };

  // Mock Hls
  function MockHls(config) {
    this.config = config || {};
    this.media = null;
    this.url = null;
    this.destroyed = false;
    this._listeners = {};
    this.levels = [{ bitrate: 5000000, width: 1920, height: 1080, name: '1080p' }];
    this._currentLevel = 0;
    this.subtitleTracks = [{ id: 0, lang: 'en', name: 'English' }];
    this._subtitleTrack = -1;
  }
  MockHls.prototype.on = function (event, cb) {
    if (!this._listeners[event]) this._listeners[event] = [];
    this._listeners[event].push(cb);
  };
  MockHls.prototype.off = function (event, cb) {
    if (!this._listeners[event]) return;
    this._listeners[event] = this._listeners[event].filter(fn => fn !== cb);
  };
  MockHls.prototype.trigger = function (event, data) {
    const list = this._listeners[event] || [];
    for (let i = 0; i < list.length; i++) {
      try { list[i](event, data || {}); } catch (_) {}
    }
  };
  MockHls.prototype.attachMedia = function (mediaElement) {
    this.media = mediaElement;
    this.trigger(MockHls.Events.MEDIA_ATTACHED, { media: mediaElement });
  };
  MockHls.prototype.detachMedia = function () {
    this.media = null;
    this.trigger(MockHls.Events.MEDIA_DETACHED, {});
  };
  MockHls.prototype.loadSource = function (url) {
    this.url = url;
    this.trigger(MockHls.Events.MANIFEST_LOADING, { url });
    const self = this;
    setTimeout(() => {
      if (!self.destroyed) {
        self.trigger(MockHls.Events.MANIFEST_LOADED, { url, levels: self.levels });
        self.trigger(MockHls.Events.MANIFEST_PARSED, { levels: self.levels });
      }
    }, 5);
  };
  MockHls.prototype.startLoad = function () { this.loading = true; };
  MockHls.prototype.stopLoad = function () { this.loading = false; };
  MockHls.prototype.destroy = function () {
    this.destroyed = true;
    this.media = null;
    this.url = null;
    this._listeners = {};
  };
  MockHls.isSupported = function () { return true; };
  MockHls.Events = {
    MANIFEST_LOADING: 'hlsManifestLoading',
    MANIFEST_LOADED: 'hlsManifestLoaded',
    MANIFEST_PARSED: 'hlsManifestParsed',
    LEVEL_SWITCHED: 'hlsLevelSwitched',
    ERROR: 'hlsError',
    MEDIA_ATTACHED: 'hlsMediaAttached',
    MEDIA_DETACHED: 'hlsMediaDetached',
    SUBTITLE_TRACKS_UPDATED: 'hlsSubtitleTracksUpdated'
  };
  MockHls.ErrorTypes = { NETWORK_ERROR: 'networkError', MEDIA_ERROR: 'mediaError' };
  MockHls.ErrorDetails = { MANIFEST_LOAD_ERROR: 'manifestLoadError', BUFFER_STALLED_ERROR: 'bufferStalledError' };
  window.Hls = MockHls;

  // Mock Fetch
  window.fetch = function (url, fetchOpts) {
    const urlStr = String(url);
    if (urlStr.includes('/health')) {
      return Promise.resolve({ ok: true, json: () => Promise.resolve({ status: 'ok' }) });
    }
    if (urlStr.includes('/api/servers')) {
      return Promise.resolve({
        ok: true,
        json: () => Promise.resolve({
