            { name: 'secret', '4k': true },
            { name: 'Nebula', '4k': false },
            { name: 'Lisbon', '4k': true }
          ]
        })
      });
    }
    if (urlStr.includes('/api/stream')) {
      return Promise.resolve({
        ok: true,
        json: () => Promise.resolve({
          success: true,
          streamUrl: 'http://127.0.0.1:8088/hls/proxy?url=https%3A%2F%2Flightspeed.st%2Fhls%2Fmaster.m3u8',
          server: 'secret',
          subtitles: [
            { label: 'English', srclang: 'en', src: 'http://127.0.0.1:8088/proxy/sub?url=en.srt' },
            { label: 'Spanish', srclang: 'es', src: 'http://127.0.0.1:8088/proxy/sub?url=es.srt' }
          ]
        })
      });
    }
    if (urlStr.includes('/proxy/sub')) {
      return Promise.resolve({
        ok: true,
        text: () => Promise.resolve('WEBVTT\n\n1\n00:00:01.000 --> 00:00:04.000\nHello\n')
      });
    }
    return Promise.resolve({ ok: true, json: () => Promise.resolve({ results: [] }) });
  };

  // Evaluate scripts
  window.eval(fs.readFileSync(configPath, 'utf8'));
  window.eval(fs.readFileSync(navPath, 'utf8'));
  window.eval(fs.readFileSync(tmdbPath, 'utf8'));
  window.eval(fs.readFileSync(homePath, 'utf8'));
