    nav: window.SpatialNav,
    player: window.PlayerController,
    osd: window.PlayerOSDController,
    video: window.document.getElementById('main-video-player')
  };
}

function sendKey(window, keyCode, key) {
  const evt = new window.KeyboardEvent('keydown', {
    keyCode: keyCode,
    which: keyCode,
    key: key || 'Unidentified',
    bubbles: true,
    cancelable: true
  });
  window.dispatchEvent(evt);
  return evt;
}

