  h.window.advanceClock(60);
  assert(osd.classList.contains('hidden'), 'HUD must hide after 4000ms');
});

await check('ADV-M3-S5', '2', 'Keypress at 3950ms boundary extends HUD visibility by full 4000ms', async () => {
  const h = createChallengerHarness();
  h.app.switchView('player');
  await h.video.play();
  h.osd.showHUD();
  const osd = h.window.document.getElementById('player-osd');

  // Advance to 3950ms (50ms before hide)
  h.window.advanceClock(3950);
  assert(!osd.classList.contains('hidden'));

  // Trigger keypress reset
  sendKey(h.window, 38, 'ArrowUp');

  // At t=4050ms (original expiry), HUD must still be visible
  h.window.advanceClock(100);
  assert(!osd.classList.contains('hidden'), 'HUD must not hide at original 4000ms after boundary reset');

  // Advance 3840ms more (total 3940ms after reset)
  h.window.advanceClock(3840);
  assert(!osd.classList.contains('hidden'), 'HUD must remain visible 3940ms after reset');

  // Advance past 4000ms from reset
  h.window.advanceClock(70);
  assert(osd.classList.contains('hidden'), 'HUD must hide 4000ms after reset');
});

await check('ADV-M3-S5', '3', 'Continuous keypress stream keeps HUD visible indefinitely', async () => {
  const h = createChallengerHarness();
  h.app.switchView('player');
  await h.video.play();
  h.osd.showHUD();
  const osd = h.window.document.getElementById('player-osd');

  // 50 keypresses every 200ms (10,000ms total)
  for (let i = 0; i < 50; i++) {
    sendKey(h.window, 39, 'ArrowRight');
    h.window.advanceClock(200);
    assert(!osd.classList.contains('hidden'), `HUD must remain visible during continuous stream at step ${i}`);
  }

  // Now let it expire
  h.window.advanceClock(4010);
  assert(osd.classList.contains('hidden'), 'HUD must hide after stream stops');
});

await check('ADV-M3-S5', '4', 'Permanent idle timer suspension while playback is paused', async () => {
  const h = createChallengerHarness();
